// Version metadata parity.
//
// The android/ project is generated by `expo prebuild` from app.json, so the
// single source of truth is app.json; package.json must agree with it. Upstream
// additionally cross-checked a committed android/app/build.gradle, a per-code
// changelog and a fastlane note — all Google-Play/F-Droid machinery that this
// fork does not ship.
import { readFile } from "node:fs/promises";

const app = JSON.parse(await readFile("app.json", "utf8"));
const pkg = JSON.parse(await readFile("package.json", "utf8"));

const name = app.expo.version;
const code = app.expo.android?.versionCode;

const errors = [];

if (pkg.version !== name) {
  errors.push(`package.json version ${pkg.version} != app.json version ${name}`);
}

if (!Number.isInteger(code) || code < 1) {
  errors.push(`app.json expo.android.versionCode is missing or not a positive integer (${code})`);
}

if (errors.length) {
  console.error(errors.join("\n"));
  process.exitCode = 1;
} else {
  console.log(`Version metadata aligned: ${name} (${code})`);
}
